#include <fstream>
#include <sstream>
#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <unordered_map>
#include <cmath>
#include <stdexcept>
#include <zlib.h>
using namespace std;
struct Rec {string key,time;int label;};
vector<string> fields(const string& s){vector<string> v;size_t a=0,b;while((b=s.find(',',a))!=string::npos){v.push_back(s.substr(a,b-a));a=b+1;}v.push_back(s.substr(a));return v;}
unsigned number(const string&s,int base,unsigned maxv){if(s.empty()||s[0]=='-')throw runtime_error("empty or negative number");size_t n=0;unsigned long v=stoul(s,&n,base);if(n!=s.size()||v>maxv)throw runtime_error("invalid numeric field");return v;}
Rec parse(string s,int attack){if(!s.empty()&&s.back()=='\r')s.pop_back();auto f=fields(s);if(f.size()<4)throw runtime_error("short CSV row");size_t consumed;double t=stod(f[0],&consumed);if(consumed!=f[0].size()||!isfinite(t)||t<0)throw runtime_error("invalid time");unsigned id=number(f[1],16,0x1fffffff),dlc=number(f[2],10,8);auto flag=f.back();if(flag!="T"&&flag!="R")throw runtime_error("invalid flag");int width=f.size()-4;if(width!=int(dlc)&&width!=8)throw runtime_error("invalid payload width");string key=to_string(id);for(int i=0;i<8;i++){unsigned x=0;if(i<int(dlc))x=number(f[3+i],16,255);else if(i<width&&!f[3+i].empty()&&number(f[3+i],16,255)!=0)throw runtime_error("byte outside DLC");key+=","+to_string(x);}key+=","+to_string(dlc);return {key,f[0],flag=="R"?0:attack};}
const array<string,5> labels={"BENIGN","DOS","FUZZY","GEAR","RPM"};
int main(int argc,char**argv){try{if(argc!=4)throw runtime_error("usage: can_accel scan|export raw_directory work_directory");string mode=argv[1],root=argv[2],out=argv[3];array<string,4> names={"DoS_dataset.csv","Fuzzy_dataset.csv","gear_dataset.csv","RPM_dataset.csv"};
if(mode=="scan"){unordered_map<string,array<unsigned long long,5>> groups;ofstream stats(out+"/source_counts.csv");stats<<"source_id,file,rows,BENIGN,DOS,FUZZY,GEAR,RPM\n";for(int source=0;source<4;source++){ifstream in(root+"/"+names[source]);if(!in)throw runtime_error("cannot open source");array<unsigned long long,5> c{};string line;unsigned long long row=0;while(getline(in,line)){row++;Rec r=parse(line,source+1);auto it=groups.find(r.key);if(it==groups.end())it=groups.emplace(r.key,array<unsigned long long,5>{}).first;it->second[r.label]++;c[r.label]++;}stats<<source<<","<<names[source]<<","<<row;for(auto n:c)stats<<","<<n;stats<<"\n";cout<<"Scanned "<<names[source]<<": "<<row<<" valid\n"<<flush;}ofstream g(out+"/group_counts.csv");g<<"ID,DATA_0,DATA_1,DATA_2,DATA_3,DATA_4,DATA_5,DATA_6,DATA_7,DLC,BENIGN,DOS,FUZZY,GEAR,RPM\n";for(auto &p:groups){g<<p.first;for(auto n:p.second)g<<","<<n;g<<"\n";}cout<<"Groups "<<groups.size()<<"\n";}
else if(mode=="export"){unordered_map<string,pair<int,string>> map;ifstream m(out+"/assignments.csv");if(!m)throw runtime_error("missing assignments");string line;getline(m,line);while(getline(m,line)){auto f=fields(line);string key=f[0];for(int i=1;i<10;i++)key+=","+f[i];map.emplace(key,make_pair(stoi(f[10]),f[11]));}array<string,3> parts={"train","validation","test"};array<gzFile,3> handles;string header="ID,DATA_0,DATA_1,DATA_2,DATA_3,DATA_4,DATA_5,DATA_6,DATA_7,DLC,y_binary,y_multiclass,y_multiclass_id,source_id,source_row,feature_group,timestamp\n";for(int i=0;i<3;i++){handles[i]=gzopen((out+"/"+parts[i]+".csv.gz").c_str(),"wb3");if(!handles[i])throw runtime_error("cannot create output");gzwrite(handles[i],header.data(),header.size());}array<unsigned long long,3> totals{};for(int source=0;source<4;source++){ifstream in(root+"/"+names[source]);unsigned long long row=0;while(getline(in,line)){row++;Rec r=parse(line,source+1);auto it=map.find(r.key);if(it==map.end())throw runtime_error("unassigned input");auto& p=it->second;string text=r.key+","+to_string(r.label!=0)+","+labels[r.label]+","+to_string(r.label)+","+to_string(source)+","+to_string(row)+","+p.second+","+r.time+"\n";int n=gzwrite(handles[p.first],text.data(),text.size());if(n!=int(text.size()))throw runtime_error("write failure");totals[p.first]++;}cout<<"Exported "<<names[source]<<": "<<row<<" rows\n"<<flush;}for(auto h:handles){if(gzclose(h)!=Z_OK)throw runtime_error("gzip close failure");}ofstream counts(out+"/export_counts.csv");counts<<"split,rows\n";for(int i=0;i<3;i++)counts<<parts[i]<<","<<totals[i]<<"\n";}
else throw runtime_error("unknown mode");return 0;}catch(const exception&e){cerr<<e.what()<<endl;return 2;}}
